// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	capacity float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

var (
	ErrCapacity = errors.New("ratelimit: capacity must be > 0")
	ErrRate     = errors.New("ratelimit: rate must be > 0")
	ErrNilClock = errors.New("ratelimit: clock must not be nil")
)

// NewLimiter creates a limiter with the given burst capacity and refill rate
// (tokens per second), starting full. If clock is nil, the real clock is used.
func NewLimiter(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrCapacity
	}
	if rate <= 0 {
		return nil, ErrRate
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		tokens:   float64(capacity),
		capacity: float64(capacity),
		rate:     rate,
		last:     now,
		clock:    clock,
	}, nil
}

// Allow reports whether one token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	t := l.tokens + elapsed*l.rate
	if t > l.capacity {
		t = l.capacity
	}
	return t
}
